#pragma once
// Shared UI helpers: fonts, flicker-free region rendering, text fitting, colours.

#include <TFT_eSPI.h>

#include "theme.h"

namespace ui {

// ---------- fonts (anti-aliased Inter, generated by tools/make_fonts.py) ----------
enum class Font : uint8_t {
    Clock,   // 60 px, digits + ':' only
    Temp,    // 40 px, digits + '-' + '°' only
    Title,   // 22 px semibold
    Body,    // 16 px regular
    Label,   // 13 px medium
};

void setFont(TFT_eSPI& g, Font f);   // no-op if that font is already loaded on g
void clearFont(TFT_eSPI& g);         // back to TFT_eSPI built-in fonts

// ---------- flicker-free regions ----------
// Paints into an off-screen sprite (coordinates relative to the region), then
// pushes it in one go, so the panel never shows a half-drawn state. Falls back
// to drawing directly through a viewport if the sprite cannot be allocated.
template <typename Paint>
void region(TFT_eSPI& tft, int16_t x, int16_t y, int16_t w, int16_t h, uint16_t bg, Paint&& paint) {
    TFT_eSprite s(&tft);
    s.setColorDepth(16);
    if (s.createSprite(w, h) != nullptr) {
        s.fillSprite(bg);
        paint(static_cast<TFT_eSPI&>(s), w, h);
        s.pushSprite(x, y);
        if (s.fontLoaded) s.unloadFont();
        s.deleteSprite();
        return;
    }
    tft.setViewport(x, y, w, h);
    tft.fillScreen(bg);
    paint(tft, w, h);
    tft.resetViewport();
}

// ---------- text ----------
// Copies text into out, shortened with "…" so it fits maxWidth in the current font.
void fitText(TFT_eSPI& g, const char* text, int16_t maxWidth, char* out, size_t outLen);

// Draw with an explicit datum and colours in one call (font must already be set).
void text(TFT_eSPI& g, const char* s, int16_t x, int16_t y, uint8_t datum, uint16_t fg, uint16_t bg);

// Running numbers: every digit gets the same cell width (like tabular figures),
// so a ticking timer doesn't jiggle. Centred horizontally on cx, baseline at y.
int16_t monoWidth(TFT_eSPI& g, const char* s);
void monoText(TFT_eSPI& g, const char* s, int16_t cx, int16_t baseline, uint16_t fg, uint16_t bg);

// "4:05" / "12:30" / "1:02:03" from milliseconds (rounded up, for countdowns).
void formatCountdown(uint32_t ms, char* out, size_t len);
// "4:05.3" / "1:02:03.4" (rounded down, for the stopwatch).
void formatStopwatch(uint32_t ms, char* out, size_t len);

// ---------- misc ----------
uint16_t calendarColour(uint8_t calendarIndex);
int roundTemp(float celsius);   // converted to the configured unit and rounded

struct Rect {
    int16_t x, y, w, h;
    bool contains(int16_t px, int16_t py) const { return px >= x && px < x + w && py >= y && py < y + h; }
    // Touch target: the visual rect plus a margin. Resistive touch jitters by a few
    // px, and visual edges near the screen border should extend to the border.
    bool hit(int16_t px, int16_t py, int16_t margin = 10) const {
        return px >= x - margin && px < x + w + margin && py >= y - margin && py < y + h + margin;
    }
};

}  // namespace ui
